def apply(patch, *options):
    return subprocess.run(
        ['git', 'apply', *options, '-'],
        cwd=Path.home(), input=patch.encode('utf-8'), capture_output=True,
    )

pending = []
for project, (incremental, combined) in PATCHES.items():
    if apply(incremental, '--reverse', '--check').returncode == 0:
        print(f'{project}: access update is already applied.')
        continue
    for patch in (incremental, combined):
        if apply(patch, '--check').returncode == 0:
            pending.append(patch)
            break
    else:
        raise SystemExit(f'{project}: source differs from the expected versions. No files changed.')

if pending:
    patch = ''.join(pending)
    checked = apply(patch, '--check')
    if checked.returncode:
        raise SystemExit(checked.stderr.decode('utf-8', errors='replace'))
    updated = apply(patch)
    if updated.returncode:
        raise SystemExit(updated.stderr.decode('utf-8', errors='replace'))
    print('Updated technician and team lead workspace access.')
